{
  "propositions": [
    {"id": "P1", "text": "A concessão da BR-101 em Santa Catarina deve ser estendida em 15 anos para incluir a construção de túneis e conter deslizamentos"},
    {"id": "P2", "text": "A obra de construção dos túneis no Morro dos Cavalos deve ser incluída no contrato atual, sem extensão da concessão"},
    {"id": "P3", "text": "A extensão da concessão deve contemplar a construção de uma rodovia paralela à BR-101 para resolver definitivamente os problemas de fluidez de trânsito"}
  ]
}
